#include "appearance.hpp"
static std::pair<double,double> weight(double t){double a=std::abs(t);if(a<=.5)return {.75-t*t,-2*t};if(a<1.5)return {.5*(1.5-a)*(1.5-a),-(1.5-a)*(t<0?-1:1)};return {0,0};}
static double tri(double z){if(z<=-1)return 0;if(z<0)return .5*(z+1)*(z+1);if(z<1)return 1-.5*(1-z)*(1-z);return 1;}
Appearance appearance(const Pair& p,const std::vector<V2>& uv){int n=uv.size();Appearance out;out.ratios.resize(n);out.stencils.resize(n*9);std::array<std::array<double,256>,3> counts{};
 for(int i=0;i<n;++i){double u=uv[i].x(),v=uv[i].y();int k=0;bool active=u>-1.5&&u<p.color.cols+.5&&v>-1.5&&v<p.color.rows+.5;int cx=active?int(std::floor(u+.5)):0,cy=active?int(std::floor(v+.5)):0;
 for(int oy=-1;oy<=1;++oy)for(int ox=-1;ox<=1;++ox,++k){auto& s=out.stencils[9*i+k];s.K.fill(1);int x=cx+ox,y=cy+oy;if(!active||x<0||y<0||x>=p.color.cols||y>=p.color.rows)continue;auto [wx,dx]=weight(u-x);auto [wy,dy]=weight(v-y);s.p=wx*wy;s.dx=dx*wy;s.dy=wx*dy;auto color=p.color.at<cv::Vec3b>(y,x);for(int ch=0;ch<3;++ch){s.levels[ch]=color[ch];counts[ch][color[ch]]+=s.p;}}}
 std::array<std::array<long double,256>,3> lower{},tail{};for(int ch=0;ch<3;++ch){long double mass=0;for(double v:counts[ch])mass+=v;out.mass[ch]=mass;if(mass==0){for(auto& r:out.ratios)r.fill(1);return out;}long double prefix=0,suffix=0;for(int l=0;l<256;++l){prefix+=counts[ch][l];lower[ch][l]=(prefix-counts[ch][l])/mass;out.q[ch][l]=counts[ch][l]/mass;int h=255-l;suffix+=counts[ch][h];tail[ch][h]=(suffix-counts[ch][h])/mass;}}
 using Key=std::array<int,5>;std::map<Key,int> unique;std::vector<int> inverse(n*9,-1);for(int i=0;i<n;++i)for(int k=0;k<9;++k){auto& s=out.stencils[9*i+k];if(s.p<=0)continue;Key key={p.a[i],p.b[i],s.levels[0],s.levels[1],s.levels[2]};unique.emplace(key,0);}int uid=0;for(auto& entry:unique)entry.second=uid++;
 struct Integral {std::array<double,8> v{};std::array<std::array<double,3>,8> dl{},du{};};std::vector<Integral> integrals(unique.size());
 struct Piece {int id,j,ch;long double lo,hi,dt;bool reflect;};std::vector<Piece> pieces;std::vector<RankQuery> queries;
 for(auto& [key,id]:unique)for(int j=0;j<4;++j){long double L[3],Q[3],T[3];for(int ch=0;ch<3;++ch){bool sign=(j>>(2-ch))&1;int level=key[2+ch];L[ch]=sign?tail[ch][level]:lower[ch][level];T[ch]=sign?lower[ch][level]:tail[ch][level];Q[ch]=out.q[ch][level];}
 long double knots[5]={0,1,1,1,1};int at=2;for(int a=0;a<3;++a)for(int b=a+1;b<3;++b){long double den=Q[a]-Q[b],r=den!=0?(L[b]-L[a])/den:1;knots[at++]=(r>0&&r<1)?r:1;}std::sort(knots,knots+5);
 for(int k=0;k<4;++k){long double lo=knots[k],hi=knots[k+1],dt=hi-lo;if(dt<=0)continue;long double mid=(lo+hi)/2,values[3];int order[3]={0,1,2};for(int ch=0;ch<3;++ch)values[ch]=L[ch]+Q[ch]*mid;std::sort(order,order+3,[&](int a,int b){return values[a]<values[b]||(values[a]==values[b]&&a<b);});int ch=order[1];long double c=L[ch]+Q[ch]*(lo+hi)/2,ct=T[ch]+Q[ch]*(1-(lo+hi)/2);bool reflect=c>ct;double C=double(reflect?ct:c),W=double(Q[ch]*dt);pieces.push_back({id,j,ch,lo,hi,dt,reflect});queries.push_back({reflect?n-key[1]:key[0],reflect?n-key[0]:key[1],C,W});queries.push_back({reflect?key[0]:n-key[1],reflect?key[1]:n-key[0],C,W});}}
 RankKernel kernel(n);auto probs=kernel.evaluate(queries);for(size_t i=0;i<pieces.size();++i){auto s=pieces[i];auto& r=integrals[s.id];for(int col=0;col<2;++col){auto v=probs[2*i+col];double left=s.reflect?-v[2]:v[1],right=s.reflect?-v[1]:v[2];int j=col?7-s.j:s.j;r.v[j]+=double(s.dt*v[0]);double dl=double(s.dt*((1-s.lo)*left+(1-s.hi)*right)),du=double(s.dt*(s.lo*left+s.hi*right));r.dl[j][s.ch]+=col?-du:dl;r.du[j][s.ch]+=col?-dl:du;}}
 for(int i=0;i<n;++i){double outside=1-(tri(uv[i].x()+.5)-tri(uv[i].x()-(p.color.cols-.5)))*(tri(uv[i].y()+.5)-tri(uv[i].y()-(p.color.rows-.5)));out.ratios[i].fill(outside);for(int k=0;k<9;++k){auto& s=out.stencils[9*i+k];if(s.p>0){Key key={p.a[i],p.b[i],s.levels[0],s.levels[1],s.levels[2]};auto& r=integrals[unique.at(key)];for(int j=0;j<8;++j){s.K[j]=r.v[j]/p.w[i];for(int ch=0;ch<3;++ch){s.dl[j][ch]=r.dl[j][ch]/p.w[i];s.du[j][ch]=r.du[j][ch]/p.w[i];}}}for(int j=0;j<8;++j)out.ratios[i][j]+=s.p*s.K[j];}}
 return out;
}
std::vector<V2> appearance_pullback(const Appearance& a,const std::vector<std::array<double,8>>& g){std::vector<V2> out(g.size(),V2::Zero());if(a.stencils.empty())return out;std::vector<double> local(a.stencils.size(),0);std::array<std::array<double,256>,3> left{},right{};
 for(size_t i=0;i<g.size();++i)for(int k=0;k<9;++k){size_t at=9*i+k;const auto& s=a.stencils[at];for(int j=0;j<8;++j)local[at]+=g[i][j]*(s.K[j]-1);for(int ch=0;ch<3;++ch){double l=0,r=0;for(int j=0;j<8;++j){double w=s.p*g[i][j],dl=w*s.dl[j][ch],du=w*s.du[j][ch];bool sign=(j>>(2-ch))&1;l+=sign?-du:dl;r+=sign?-dl:du;}left[ch][s.levels[ch]]+=l;right[ch][s.levels[ch]]+=r;}}
 for(int ch=0;ch<3;++ch){if(a.mass[ch]==0)continue;std::array<double,256> dq{};double sum=0;for(int l=255;l>=0;--l){sum+=left[ch][l]+right[ch][l];dq[l]=sum-left[ch][l];}long double dot=0;for(int l=0;l<256;++l)dot+=a.q[ch][l]*dq[l];for(size_t i=0;i<a.stencils.size();++i)local[i]+=double((dq[a.stencils[i].levels[ch]]-dot)/a.mass[ch]);}
 for(size_t i=0;i<g.size();++i)for(int k=0;k<9;++k){const auto& s=a.stencils[9*i+k];out[i]+=local[9*i+k]*V2(s.dx,s.dy);}return out;
}
static double root(const std::function<double(double)>& f,double a,double b,double tol){double fa=f(a),fb=f(b);if(fa==0)return a;if(fb==0)return b;for(int i=0;i<100;++i){double mid=(a+b)/2,fm=f(mid);if(fm==0||b-a<tol)return mid;if((fa<0)==(fm<0)){a=mid;fa=fm;}else b=mid;}return (a+b)/2;}
std::pair<double,std::vector<V2>> coarse_appearance(const Pair& p,const std::vector<V2>& uv){int n=uv.size();std::vector<double> b(n),x(n),z(n),d(n);std::vector<V2> db(n,V2::Zero());for(int i=0;i<n;++i){double u=uv[i].x(),v=uv[i].y();if(u<=-1.5||u>=p.gray.cols+.5||v<=-1.5||v>=p.gray.rows+.5)continue;int cx=std::floor(u+.5),cy=std::floor(v+.5);for(int oy=-1;oy<=1;++oy)for(int ox=-1;ox<=1;++ox){int xx=cx+ox,yy=cy+oy;if(xx<0||yy<0||xx>=p.gray.cols||yy>=p.gray.rows)continue;auto [wx,dx]=weight(u-xx);auto [wy,dy]=weight(v-yy);double value=p.gray_rank[p.gray.at<uint8_t>(yy,xx)];b[i]+=value*wx*wy;db[i]+=value*V2(dx*wy,wx*dy);}}
 for(int i=0;i<n;++i){d[i]=(3*p.c[i]*p.c[i]+p.w[i]*p.w[i]-1)/2;x[i]=p.c[i]*b[i];z[i]=d[i]*(3*b[i]*b[i]-1)/2;}
 struct Fit{double value,A,B,derivative;};auto fit=[&](double B){auto ga=[&](double A){double sum=0;for(int i=0;i<n;++i)sum-=x[i]/(1+A*x[i]+B*z[i]);return sum/n;};double lo=-1-B,hi=1+B,A,side;if(ga(lo)>=0){A=lo;side=-1;}else if(ga(hi)<=0){A=hi;side=1;}else{A=root(ga,lo,hi,5e-15);side=0;}double val=0,gb=0;for(int i=0;i<n;++i){double q=A*x[i]+B*z[i];val-=std::log1p(q);gb-=z[i]/(1+q);}return Fit{val/n,A,B,gb/n+side*ga(A)};};auto low=fit(0),high=fit(.5);auto best=low.derivative>=0?low:high.derivative<=0?high:fit(root([&](double B){return fit(B).derivative;},0,.5,5e-15));if(best.value>0)best={0,0,0,0};for(int i=0;i<n;++i)db[i]*=-(best.A*p.c[i]+3*best.B*d[i]*b[i])/(1+best.A*x[i]+best.B*z[i])/n;return {best.value,db};
}
